do $$
begin
  if not exists (
    select 1
    from pg_type t
    join pg_namespace n on n.oid = t.typnamespace
    where n.nspname = 'iam'
      and t.typname = 'platform_user_status'
  ) then
    create type iam.platform_user_status as enum (
      'pending_activation',
      'active',
      'suspended'
    );
  end if;
end
$$;

-- Avoid ALTER COLUMN ... TYPE: Postgres rewrites leftover text CHECKs into
--   iam.platform_user_status = text
-- and fails. Swap via a new enum column instead.
do $$
declare
  r record;
  v_typnamespace text;
  v_typname text;
begin
  -- Drop every CHECK on this table (only status CHECK existed historically).
  for r in
    select c.conname
    from pg_constraint c
    join pg_class rel on rel.oid = c.conrelid
    join pg_namespace nsp on nsp.oid = rel.relnamespace
    where nsp.nspname = 'iam'
      and rel.relname = 'platform_user_profiles'
      and c.contype = 'c'
  loop
    execute format(
      'alter table iam.platform_user_profiles drop constraint %I',
      r.conname
    );
  end loop;

  select typ_nsp.nspname, typ.typname
  into v_typnamespace, v_typname
  from pg_attribute a
  join pg_class rel on rel.oid = a.attrelid
  join pg_namespace nsp on nsp.oid = rel.relnamespace
  join pg_type typ on typ.oid = a.atttypid
  join pg_namespace typ_nsp on typ_nsp.oid = typ.typnamespace
  where nsp.nspname = 'iam'
    and rel.relname = 'platform_user_profiles'
    and a.attname = 'status'
    and not a.attisdropped;

  if v_typnamespace = 'iam' and v_typname = 'platform_user_status' then
    alter table iam.platform_user_profiles
      alter column status set default 'active'::iam.platform_user_status,
      alter column status set not null;
    return;
  end if;

  -- Clean leftover from a previous failed attempt.
  alter table iam.platform_user_profiles
    drop column if exists status_enum;

  alter table iam.platform_user_profiles
    add column status_enum iam.platform_user_status;

  update iam.platform_user_profiles
  set status_enum = (status::text)::iam.platform_user_status;

  alter table iam.platform_user_profiles
    alter column status drop default;

  alter table iam.platform_user_profiles
    drop column status;

  alter table iam.platform_user_profiles
    rename column status_enum to status;

  alter table iam.platform_user_profiles
    alter column status set default 'active'::iam.platform_user_status,
    alter column status set not null;
end
$$;
